#!/usr/bin/env python3
"""Single source for both C4 Markdown formats; generated by render.py."""
import sys
from html import escape
from textwrap import wrap
from canvas import Canvas

TITLE = 'System Context'
BOUNDARY = 'Document DB platform'
NODES = [('developer',
  'App developer',
  'Person',
  'app/; sdk/',
  'Declares schemas and Effect handlers',
  False),
 ('caller',
  'Application caller',
  'Person',
  'sdk/client.ts',
  'Players and authenticated tenant users',
  False),
 ('operator',
  'Platform operator',
  'Person',
  'scripts/',
  'Tenants, auth, backups and log analysis',
  False),
 ('db',
  'Document DB platform',
  'Software system',
  'platform/',
  'Effect; SQLite writes; DuckDB reads; tenant routing',
  True),
 ('objects',
  'Object storage',
  'External system',
  'S3_BASE_URL or LOCAL_OBJECT_DIR',
  'Immutable snapshots and manifests',
  False),
 ('analytics',
  'Analytics consumer',
  'External system',
  'scripts/logs.ts; scripts/duckdb/',
  'Named catalog or offline SQL',
  False),
 ('k6',
  'k6 load generator',
  'External system',
  'perf/*.js',
  'HTTP load and raw metric points',
  False)]
EDGES = [('developer', 'db', 'Schema and named handlers (TypeScript)'),
 ('caller', 'db', 'HTTP JSON; bearer credentials; X-Trace-Id'),
 ('operator', 'db', 'Admin HTTP / CLI; tenant and backup operations'),
 ('db', 'objects', 'S3 HTTPS or local files; snapshots and manifests'),
 ('db', 'analytics', 'Query results; derived event-log rows'),
 ('k6', 'db', 'HTTP scenarios and trace headers')]
NOTES = 'Tenant identity comes from API keys or headless Better Auth session bearers when enabled. Postgres is\npart of the platform, shown at Level 2; no external identity provider is wired. No application SQL crosses\nthe client boundary. This audit includes items 23-29, MT-01 through MT-10 and reader supervision.\nBackup publication currently works only with tenancy off; tenant recovery is a follow-up.'
NAME = 'c4-context-document-db'


def picture():
    cv = Canvas(width=72, height=260)
    row = 2
    for inside in (True, False):
        group = [n for n in NODES if n[5] == inside]
        if not inside:
            cv.frame(0, 0, row, 71, BOUNDARY)
            row += 2
        for offset in range(0, len(group), 2):
            bottoms = []
            for col, (_, title, kind, path, detail, _) in enumerate(group[offset:offset+2]):
                lines = [part for line in [title, '[' + kind + ']', path, detail]
                         for part in wrap(line, 28, break_on_hyphens=False)]
                bottoms.append(cv.box(row, 3 + col*35, 32, lines))
            row = max(bottoms) + 2
    return cv.render()


def mermaid():
    lines = ['flowchart TB', '    subgraph platform["' + BOUNDARY + '"]']
    for inside in (True, False):
        for id, title, kind, path, detail, within in NODES:
            if within == inside:
                label = '<br/>'.join(escape(s, quote=True) for s in [title, '['+kind+']', path, detail])
                lines.append('        ' + id + '["' + label + '"]')
        if inside:
            lines.append('    end')
    for i, (a, b, label) in enumerate(EDGES, 1):
        lines.append(f'    {a} -->|"({i}) {label}"| {b}')
    lines += ['    classDef planned stroke-dasharray: 5 3',
              '    classDef person fill:#fff,stroke-width:2px',
              '    classDef external fill:#f4f4f4']
    for id, _, kind, _, _, inside in NODES:
        if kind == 'Person':
            lines.append(f'    class {id} person')
        elif not inside:
            lines.append(f'    class {id} external')
    return '\n'.join(lines)


def document(github):
    text = '# ' + TITLE + '\n\nAudited against landed main `cd669d1` on 2026-10-11 (reflection astra-2). Both formats are generated from\n'
    text += '`diagrams/' + NAME + '.py`; numbered relationships are identical. All boxes describe landed code.\n\n'
    if github:
        text += '```mermaid\n' + mermaid() + '\n```\n'
    else:
        text += '<!-- c4-render: diagrams/' + NAME + '.py -->\n\n```text\n' + picture() + '\n```\n'
    names = {n[0]: n[1] for n in NODES}
    text += '\n## Relationships\n\n| # | From | To | Relationship |\n| - | --- | --- | --- |\n'
    for i, (a,b,label) in enumerate(EDGES,1):
        text += f'| {i} | {names[a]} | {names[b]} | {label} |\n'
    return text + '\n## Runtime notes\n\n' + NOTES + '\n'


if __name__ == '__main__':
    if '--github' in sys.argv:
        print(document(True), end='')
    elif '--terminal' in sys.argv:
        print(document(False), end='')
    else:
        print(picture())
